"""
    This method looks for active_words in subject in a case-insensitive fashion

    Parameters
    ----------
    subject: string, required
        email subject
    active_words: string, required
        active words represented in a comma delimited fashion

    Returns
    -------
    True
        If any active words were found in subject or,
        No active words are configured
    False
        If no active words were found in subject
    """
def search_active_words(subject: Any, active_words: Any) -> object {
    if not active_words {
        return True;
    } else {
        lower_words = [
            word.strip().lower() for word in filter(None, active_words.split(','))
        ];
        subject_lower = subject.lower();
        for word in lower_words {
            if (word in subject_lower) {
                return True;
            }
        }
    }
    return False;
}

"""
    Find the root of f(x) = 0 using the Newton-Raphson method recursively.

    Parameters
    ----------
        f       - function
        f_prime - derivative of f
        x0      - starting value
        tol     - tolerance

    Returns
    -------
    root of f(x)
    """
def newton(f: Any, f_prime: Any, x0: Any, tol: Any) -> object {
    if (abs(f(x0)) < tol) {
        return x0;
    } else {
        x1 = x0 - (f(x0) / f_prime(x0));
        print("x0 = ", x0, "f(x0) = ", f(x0), "f'(x0) =", f_prime(x0), "x1 = ", x1);
        return newton(f, f_prime, x1, tol);
    }
}

